        {
          "n": 1,
          "text": "Como é bom e agradável quando os irmãos convivem em união!"
        },
        {
          "n": 2,
          "text": "É como óleo precioso derramado sobre a cabeça, que desce pela barba, a barba de Arão, até a gola das suas vestes."
        },
        {
          "n": 3,
          "text": "É como o orvalho do Hermom quando desce sobre os montes de Sião. Ali o Senhor concede a bênção da vida para sempre."
        }
